class ClimaOpenMeteo:
    URL = "https://archive-api.open-meteo.com/v1/archive"
    CIDADES = {
        "N": ("Belém", -1.46, -48.49),
        "NE": ("Recife", -8.05, -34.88),
        "SE": ("São Paulo", -23.55, -46.63),
        "S": ("Porto Alegre", -30.03, -51.23),
    }

    def extrair(self, inicio, fim):
        # O contrato vai até antes de fim; a Open-Meteo inclui end_date: pede até a véspera.
        ultimo_dia = (pd.Timestamp(fim) - pd.Timedelta(days=1)).strftime("%Y-%m-%d")
        tabelas = []
        for subsistema, (cidade, lat, lon) in self.CIDADES.items():
            resposta = httpx.get(self.URL, params={
                "latitude": lat, "longitude": lon,
                "start_date": inicio, "end_date": ultimo_dia,
                "hourly": "temperature_2m", "timezone": "America/Sao_Paulo",
            }, timeout=30.0)
            resposta.raise_for_status()
            horas = resposta.json()["hourly"]
            tabelas.append(pd.DataFrame({
                "id_subsistema": subsistema,
                "instante": pd.to_datetime(horas["time"]),
                "temperatura_c": horas["temperature_2m"],
            }))
        return pd.concat(tabelas, ignore_index=True)
